fn decode_fpextins(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffbf0f50 != 0xfeb00a40 {
        return Err(DecodeError::Unallocated);
    }
    // 1111|11|101|D=x|110000|Vd=xxxx|1|0|size=10|op=x|1|M=x|0|Vm=xxxx
    let D: u8 = ((bits >> 22) & 0x1) as u8;
    let Vd: u8 = ((bits >> 12) & 0xf) as u8;
    let M: u8 = ((bits >> 5) & 0x1) as u8;
    let Vm: u8 = (bits & 0xf) as u8;
    match bits & 0x380 {
        0x200 => {
            // VMOVX
            // VMOVX{<q>}.F16  <Sd>, <Sm>
            Ok(Instruction::VmovxA1 {
                Sd: SReg::new(Vd << 1 | D),
                Sm: SReg::new(Vm << 1 | M),
            })
        }
        0x280 => {
            // VINS
            // VINS{<q>}.F16  <Sd>, <Sm>
            Ok(Instruction::VinsA1 {
                Sd: SReg::new(Vd << 1 | D),
                Sm: SReg::new(Vm << 1 | M),
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

fn decode_fpimm(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xfb00c50 != 0xeb00800 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|11101|D=x|11|imm4H=xxxx|Vd=xxxx|10|size=xx|x0x0|imm4L=xxxx
    let cond: u8 = (bits >> 28) as u8;
    let imm4H: u8 = ((bits >> 16) & 0xf) as u8;
    let imm4L: u8 = (bits & 0xf) as u8;
    let D: u8 = ((bits >> 22) & 0x1) as u8;
    let Vd: u8 = ((bits >> 12) & 0xf) as u8;
    match bits & 0x300 {
        0x100 => {
            // VMOV (immediate) — Half-precision scalar
            // VMOV{<c>}{<q>}.F16  <Sd>, #<imm>
            let unpredictable: bool = bits & 0xa0 != 0x0 || cond != 0b1110;
            let imm: u64 = shared::VFPExpandImm_16(imm4H << 4 | imm4L) as u64;
            let d: u8 = Vd << 1 | D;
            Ok(Instruction::VmovIA2H {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Sd: SReg::new(d),
                imm: imm & 0xffff,
                unpredictable,
            })
        }
        0x200 => {
            // VMOV (immediate) — Single-precision scalar
            // VMOV{<c>}{<q>}.F32  <Sd>, #<imm>
            let unpredictable: bool = bits & 0xa0 != 0x0;
            let imm: u64 = shared::VFPExpandImm_32(imm4H << 4 | imm4L) as u64;
            let d: u8 = Vd << 1 | D;
            Ok(Instruction::VmovIA2S {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Sd: SReg::new(d),
                imm: imm & 0xffffffff,
                unpredictable,
            })
        }
        0x300 => {
            // VMOV (immediate) — Double-precision scalar
            // VMOV{<c>}{<q>}.F64  <Dd>, #<imm>
            let unpredictable: bool = bits & 0xa0 != 0x0;
            let imm: u64 = shared::VFPExpandImm_64(imm4H << 4 | imm4L);
            let d: u8 = D << 4 | Vd;
            Ok(Instruction::VmovIA2D {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Dd: DReg::new(d),
                imm,
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

