fn decode_movcpgp32(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xf000e10 != 0xe000e10 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|11|10|opc1=xxx|L=x|CRn=xxxx|Rt=xxxx|1|11|cp15=x|opc2=xxx|1|CRm=xxxx
    let Rt: u8 = ((bits >> 12) & 0xf) as u8;
    let cp15: u8 = ((bits >> 8) & 0x1) as u8;
    let cond: u8 = (bits >> 28) as u8;
    let opc1: u8 = ((bits >> 21) & 0x7) as u8;
    let CRn: u8 = ((bits >> 16) & 0xf) as u8;
    let opc2: u8 = ((bits >> 5) & 0x7) as u8;
    let CRm: u8 = (bits & 0xf) as u8;
    match bits & 0x100000 {
        0 => {
            // MCR
            // MCR{<c>}{<q>}  <coproc>, {#}<opc1>, <Rt>, <CRn>, <CRm>{, {#}<opc2>}
            let unpredictable: bool = Rt == 15;
            Ok(Instruction::McrA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                coproc: match Coproc::from_bits(cp15) {
                    Some(symbol) => symbol,
                    None => return Err(DecodeError::Unallocated),
                },
                opc1,
                Rt: GpReg::new(Rt),
                CRn,
                CRm,
                opc2,
                unpredictable,
            })
        }
        0x100000 => {
            // MRC
            // MRC{<c>}{<q>}  <coproc>, {#}<opc1>, <Rt>, <CRn>, <CRm>{, {#}<opc2>}
            Ok(Instruction::MrcA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                coproc: match Coproc::from_bits(cp15) {
                    Some(symbol) => symbol,
                    None => return Err(DecodeError::Unallocated),
                },
                opc1,
                Rt: GpReg::new(Rt),
                CRn,
                CRm,
                opc2,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

